 \right| \left. \begin{array}{ c c }
 \mathrm{\stackrel{}{4} }& \\
 \mathrm{\stackrel{}{1} }& 
 \end{array}\right| 
 \begin{array}{ l l }
 \text{відновник, окиснення}& \\[7pt]
 \text{окисник, відновлення}&
