 $$
 \mathrm{
 3\overset{+4}{\underline{Pb}}O_2+\overset{+3}{\underline{\underline{Cr}}}_2(SO_4)_3+H_2O=3\overset{+2}{\underline{Pb}}SO_4+2H_2\overset{+6}{\underline{\underline{Cr}}}O_4
