 Завдання скеровано на перевірку вміння перетворювати схеми окисно-відновних реакцій на хімічні рівняння методом електронного балансу.
 $$
 \mathrm{
 3\overset{0}{P}+5\overset{+1}{H}\overset{+5}{N}\overset{-2}{O}_3+2\overset{+1}{H}_2\overset{-2}{O}=3\overset{+1}{H}_3\overset{+5}{P}\overset{-2}{O}_4+5\overset{+2}{N}\overset{-2}{O}}
$$ 
 \begin{gather*}
 \left. \begin{array}{ c c }
 \overset{0}{\mathrm{P}}-5\overline{e}\rightarrow \overset{+5}{\mathrm{P}}& \\
 \overset{+5}{\mathrm{N}}+3\overline{e}\rightarrow \overset{+2}{\mathrm{N}}& 
 \end{array}\right| 
 \left. \begin{array}{ l l }
 15
 \end{array}\right.
 \left| \begin{array}{ l l }
 \ \ 3 & \\
